import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * Parses the procedural pixmap command script.
 *
 * <p>One command per line, whitespace separated tokens, blank lines and lines starting
 * with {@code #} are ignored. The supported opcodes are documented in the project README
 * and the {@link Op} enum.</p>
 */
public final class ScriptParser {

    /** Supported drawing commands. */
    public enum Op {
        SIZE,
        FILL,
        RECT,
        LINE,
        CIRCLE,
        PIXEL
    }

    /** A single parsed command (opcode + integer arguments). */
    public static final class Command {
        public final Op op;
        public final int[] args;
        public final int lineNumber;

        Command(Op op, int[] args, int lineNumber) {
            this.op = op;
            this.args = args;
            this.lineNumber = lineNumber;
        }
    }

    private ScriptParser() {
    }

    /**
     * Reads the file at {@code path}, skipping blank lines and lines starting with {@code #},
     * and returns the ordered list of commands.
     *
     * @throws IOException          if the file cannot be read
     * @throws ScriptParseException if a line is malformed
     */
    public static List<Command> parse(Path path) throws IOException {
        List<String> lines = Files.readAllLines(path, StandardCharsets.UTF_8);
        List<Command> out = new ArrayList<>();
        boolean sizeEncountered = false;

        for (int i = 0; i < lines.size(); i++) {
            String raw = lines.get(i);
            int lineNumber = i + 1;
            String trimmed = raw.trim();

            // Skip blank lines and comments.
            if (trimmed.isEmpty() || trimmed.startsWith("#")) {
                continue;
            }

            String[] tokens = trimmed.split("\\s+");
            Op op;
            try {
                op = Op.valueOf(tokens[0]);
            } catch (IllegalArgumentException ex) {
                throw new ScriptParseException(
                    "Unknown command '" + tokens[0] + "' on line " + lineNumber, lineNumber);
            }

            int expected = expectedArgCount(op);
            if (tokens.length - 1 != expected) {
                throw new ScriptParseException(
                    "Command " + op + " on line " + lineNumber + " expected "
                        + expected + " arguments but got " + (tokens.length - 1),
                    lineNumber);
            }

            int[] args = new int[expected];
            for (int j = 0; j < expected; j++) {
                try {
                    args[j] = Integer.parseInt(tokens[j + 1]);
                } catch (NumberFormatException nfe) {
                    throw new ScriptParseException(
                        "Argument '" + tokens[j + 1] + "' on line " + lineNumber
                            + " for command " + op + " is not a valid integer",
                        lineNumber, nfe);
                }
            }

            // SIZE must come first.
            if (op == Op.SIZE) {
                if (sizeEncountered) {
                    throw new ScriptParseException(
                        "Duplicate SIZE command on line " + lineNumber, lineNumber);
                }
                sizeEncountered = true;
                if (args[0] <= 0 || args[1] <= 0) {
                    throw new ScriptParseException(
                        "SIZE on line " + lineNumber + " requires positive dimensions",
                        lineNumber);
                }
            } else if (!sizeEncountered) {
                throw new ScriptParseException(
                    "Command " + op + " on line " + lineNumber
                        + " appeared before any SIZE directive",
                    lineNumber);
            }

            out.add(new Command(op, args, lineNumber));
        }

        if (!sizeEncountered) {
            throw new ScriptParseException(
                "Script does not contain a SIZE command", -1);
        }

        return out;
    }

    private static int expectedArgCount(Op op) {
        switch (op) {
            case SIZE:   return 2;   // width height
            case FILL:   return 4;   // r g b a
            case RECT:   return 8;   // x y w h r g b a
            case LINE:   return 8;   // x1 y1 x2 y2 r g b a
            case CIRCLE: return 7;   // cx cy radius r g b a
            case PIXEL:  return 6;   // x y r g b a
            default:
                throw new IllegalStateException("unreachable: " + op);
        }
    }

    /** Thrown for any script-level parsing error. Carries the offending source line. */
    public static final class ScriptParseException extends RuntimeException {
        private static final long serialVersionUID = 1L;
        public final int lineNumber;

        public ScriptParseException(String message, int lineNumber) {
            super(message);
            this.lineNumber = lineNumber;
        }

        public ScriptParseException(String message, int lineNumber, Throwable cause) {
            super(message, cause);
            this.lineNumber = lineNumber;
        }
    }
}

package com.pochi.pixmaprenderer;

import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.files.FileHandle;
import com.badlogic.gdx.graphics.Pixmap;
import com.badlogic.gdx.graphics.PixmapIO;

import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

/**
 * {@link com.badlogic.gdx.ApplicationListener} implementation that runs inside a
 * {@link com.badlogic.gdx.backends.headless.HeadlessApplication} and renders a single
 * pixmap from a previously parsed script.
 *
 * <p>All rendering and file I/O happen on the libGDX thread inside {@link #create()} so
 * that {@link com.badlogic.gdx.backends.headless.HeadlessNativesLoader} has finished
 * loading the natives and JNI-backed {@link Pixmap} calls are safe.</p>
 */
public final class PixmapRendererListener extends ApplicationAdapter {

    /** Lock that {@link #create()} releases once the PNG has been written. */
    private final Object completionLock = new Object();
    /** Signalled once create() finished successfully or with an error. */
    private boolean completed;

    /** Result dimensions (filled in once the pixmap has been created). */
    private int width = -1;
    private int height = -1;
    /** Number of drawing commands processed (excluding {@code SIZE}). */
    private int commandCount;

    /** Set in create() when an unrecoverable error occurs. */
    private Throwable failure;

    private final List<ScriptParser.Command> commands;
    private final Path outputPath;

    public PixmapRendererListener(List<ScriptParser.Command> commands, Path outputPath) {
        this.commands = commands;
        this.outputPath = outputPath;
    }

    /** Block the calling thread until {@link #create()} finishes, then return. */
    public void awaitCompletion() throws InterruptedException {
        synchronized (completionLock) {
            long deadline = System.currentTimeMillis() + 60_000L;
            while (!completed) {
                long remaining = deadline - System.currentTimeMillis();
                if (remaining <= 0) {
                    throw new InterruptedException(
                        "Timed out waiting for headless render to finish");
                }
                completionLock.wait(remaining);
            }
        }
    }

    public int getWidth() {
        return width;
    }

    public int getHeight() {
        return height;
    }

    public int getCommandCount() {
        return commandCount;
    }

    public Throwable getFailure() {
        return failure;
    }

    @Override
    public void create() {
        Pixmap pixmap = null;
        try {
            int[] size = findSizeArgs();
            pixmap = new Pixmap(size[0], size[1], Pixmap.Format.RGBA8888);
            // Use no-blending so FILL/RECT truly overwrite prior content
            // regardless of alpha values.
            pixmap.setBlending(Pixmap.Blending.None);

            for (ScriptParser.Command cmd : commands) {
                applyCommand(pixmap, cmd);
            }

            this.width = pixmap.getWidth();
            this.height = pixmap.getHeight();

            FileHandle out = Gdx.files.absolute(outputPath.toString());
            // Ensure parent directory exists.
            Path parent = outputPath.toAbsolutePath().getParent();
            if (parent != null) {
                java.io.File parentDir = parent.toFile();
                if (!parentDir.exists() && !parentDir.mkdirs() && !parentDir.exists()) {
                    throw new java.io.IOException(
                        "Unable to create output directory " + parentDir);
                }
            }

            PixmapIO.writePNG(out, pixmap);

            // Force any buffered output to hit disk before we exit().
            out.file().getAbsoluteFile();
        } catch (Throwable t) {
            this.failure = t;
        } finally {
            if (pixmap != null) {
                try {
                    pixmap.dispose();
                } catch (Throwable disposeError) {
                    if (failure == null) {
                        failure = disposeError;
                    }
                }
            }
            synchronized (completionLock) {
                completed = true;
                completionLock.notifyAll();
            }
            // Request that the application loop terminate.
            try {
                Gdx.app.exit();
            } catch (Throwable ignored) {
                // Gdx.app may already be shutting down; nothing else to do.
            }
        }
    }

    private int[] findSizeArgs() {
        for (ScriptParser.Command cmd : commands) {
            if (cmd.op == ScriptParser.Op.SIZE) {
                return cmd.args;
            }
        }
        throw new ScriptParser.ScriptParseException(
            "Script must contain a SIZE command", -1);
    }

    private void applyCommand(Pixmap pixmap, ScriptParser.Command cmd) {
        switch (cmd.op) {
            case SIZE:
                // Already handled; nothing to draw but counts as a layout command.
                return;

            case FILL: {
                setColor(pixmap, cmd.args, 0);
                pixmap.fill();
                commandCount++;
                return;
            }

            case RECT: {
                pixmap.setColor(
                    byteNorm(cmd.args[4]),
                    byteNorm(cmd.args[5]),
                    byteNorm(cmd.args[6]),
                    byteNorm(cmd.args[7]));
                pixmap.fillRectangle(cmd.args[0], cmd.args[1], cmd.args[2], cmd.args[3]);
                commandCount++;
                return;
            }

            case LINE: {
                pixmap.setColor(
                    byteNorm(cmd.args[4]),
                    byteNorm(cmd.args[5]),
                    byteNorm(cmd.args[6]),
                    byteNorm(cmd.args[7]));
                pixmap.drawLine(cmd.args[0], cmd.args[1], cmd.args[2], cmd.args[3]);
                commandCount++;
                return;
            }

            case CIRCLE: {
                pixmap.setColor(
                    byteNorm(cmd.args[3]),
                    byteNorm(cmd.args[4]),
                    byteNorm(cmd.args[5]),
                    byteNorm(cmd.args[6]));
                pixmap.fillCircle(cmd.args[0], cmd.args[1], cmd.args[2]);
                commandCount++;
                return;
            }

            case PIXEL: {
                pixmap.setColor(
                    byteNorm(cmd.args[2]),
                    byteNorm(cmd.args[3]),
                    byteNorm(cmd.args[4]),
                    byteNorm(cmd.args[5]));
                pixmap.drawPixel(cmd.args[0], cmd.args[1]);
                commandCount++;
                return;
            }

            default:
                throw new ScriptParser.ScriptParseException(
                    "Unsupported op " + cmd.op + " on line " + cmd.lineNumber,
                    cmd.lineNumber);
        }
    }

    private static float byteNorm(int v) {
        return v / 255f;
    }

    /**
     * Convenience for {@code FILL} which has color components immediately
     * after the opcode (no positional arguments).
     */
    private static void setColor(Pixmap pixmap, int[] args, int offset) {
        pixmap.setColor(
            byteNorm(args[offset]),
            byteNorm(args[offset + 1]),
            byteNorm(args[offset + 2]),
            byteNorm(args[offset + 3]));
    }

    /** Convenience for tests / run.sh callers that prefer path strings. */
    @SuppressWarnings("unused")
    static PixmapRendererListener fromPaths(List<ScriptParser.Command> cmds, String outPath) {
        return new PixmapRendererListener(cmds, Paths.get(outPath));
    }
}

package com.pochi.pixmaprenderer;

import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;
import com.badlogic.gdx.backends.headless.HeadlessNativesLoader;

import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

/**
 * Command-line entrypoint that boots a {@link HeadlessApplication}, dispatches a parsed
 * drawing script through {@link PixmapRendererListener}, and prints the summary line
 * that {@code run.sh} looks for.
 *
 * <p>Usage: {@code java HeadlessPixmapLauncher <input-script> <output-png>}</p>
 */
public final class HeadlessPixmapLauncher {

    private HeadlessPixmapLauncher() {
    }

    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println(
                "Usage: HeadlessPixmapLauncher <input-script> <output-png>");
            System.exit(2);
        }

        Path inputPath = Paths.get(args[0]).toAbsolutePath();
        Path outputPath = Paths.get(args[1]).toAbsolutePath();

        // Parse script on the main thread before touching libGDX so that any
        // IO / parse errors are reported before we boot a native-backed backend.
        final List<ScriptParser.Command> commands;
        try {
            commands = ScriptParser.parse(inputPath);
        } catch (IOException ioe) {
            System.err.println(
                "Failed to read input script '" + inputPath + "': " + ioe);
            System.exit(3);
            return;
        } catch (ScriptParser.ScriptParseException spe) {
            System.err.println(
                "Bad input script '" + inputPath + "': " + spe.getMessage());
            System.exit(3);
            return;
        }

        // Make sure the libGDX native libraries are extracted and loaded before
        // the HeadlessApplication thread starts touching JNI-backed classes.
        HeadlessNativesLoader.load();

        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        // Up the iteration count so any postRunnable-during-create work still gets
        // a chance to fire before shutdown logic runs.
        config.updatesPerSecond = -1;

        PixmapRendererListener listener =
            new PixmapRendererListener(commands, outputPath);

        HeadlessApplication app = new HeadlessApplication(listener, config);

        Throwable renderFailure = null;
        try {
            listener.awaitCompletion();
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
            renderFailure = ie;
        }

        if (listener.getFailure() != null) {
            renderFailure = listener.getFailure();
        }

        // Give libGDX a moment to actually wind down its thread before we tear
        // the JVM down — otherwise the PNG writer can race with shutdown.
        try {
            app.exit();
        } catch (Throwable ignored) {
            // Already shutting down; ignore.
        }

        if (renderFailure != null) {
            System.err.println("Render failed: " + renderFailure);
            renderFailure.printStackTrace(System.err);
            System.exit(4);
            return;
        }

        // Print the summary line. Format must remain stable so the test harness
        // can parse it.
        System.out.println(
            "RENDER_OK width=" + listener.getWidth()
                + " height=" + listener.getHeight()
                + " commands=" + listener.getCommandCount());

        System.exit(0);
    }
}

